@page "/notepad"
@rendermode InteractiveServer
@inject IJSRuntime JS
@implements IAsyncDisposable

<PageTitle>Notepad</PageTitle>

<h1>Notepad</h1>

<textarea @ref="_textareaRef" @bind="_content" @bind:event="oninput" rows="15" style="width:100%;"></textarea>

<div style="margin-top: 0.5rem; display: flex; align-items: center; gap: 1rem;">
    <button class="btn btn-primary" @onclick="SaveNowAsync">Save now</button>
    <button class="btn btn-danger" @onclick="ClearAsync">Clear</button>
    @if (_lastSaved is not null)
    {
        <span>Last saved at @_lastSaved.Value.ToString("HH:mm:ss")</span>
    }
</div>

@code {
    private ElementReference _textareaRef;
    private NotepadInterop? _interop;
    private string _content = string.Empty;
    private DateTime? _lastSaved;
    private System.Threading.Timer? _autoSaveTimer;
    private string _lastSavedContent = string.Empty;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _interop = new NotepadInterop(JS);
            await _interop.InitializeAsync();

            _content = await _interop.LoadAsync() ?? string.Empty;
            _lastSavedContent = _content;

            _autoSaveTimer = new System.Threading.Timer(
                async _ => await InvokeAsync(AutoSaveAsync),
                null,
                TimeSpan.FromSeconds(30),
                TimeSpan.FromSeconds(30));

            StateHasChanged();
        }
    }

    private async Task AutoSaveAsync()
    {
        if (_content != _lastSavedContent)
        {
            await SaveAsync();
            StateHasChanged();
        }
    }

    private async Task SaveNowAsync()
    {
        await SaveAsync();
    }

    private async Task SaveAsync()
    {
        if (_interop is null) return;
        await _interop.SaveAsync(_content);
        _lastSavedContent = _content;
        _lastSaved = DateTime.Now;
    }

    private async Task ClearAsync()
    {
        if (_interop is null) return;
        _content = string.Empty;
        _lastSavedContent = string.Empty;
        _lastSaved = null;
        await _interop.ClearAsync();
    }

    private bool HasUnsavedChanges => _content != _lastSavedContent;

    protected override async Task OnAfterRenderAsync(bool firstRender, bool _)
        => await Task.CompletedTask;

    async ValueTask IAsyncDisposable.DisposeAsync()
    {
        _autoSaveTimer?.Dispose();

        try
        {
            if (_interop is not null)
                await _interop.DisposeAsync();
        }
        catch (JSDisconnectedException) { }
    }
}

